        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol
        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        self.spy_sma = self.SMA(self.spy, 100, Resolution.Daily)
        self.aapl_rsi = self.RSI(self.aapl, 14, MovingAverageType.Wilders, Resolution.Daily)

        self.previous_spy_sma_delta = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.a_lot = 0
        self.b_lot = 0
        self.a_pending = False
        self.b_pending = False
        self.order_actions = {}

    def OnData(self, data):
        if data.Bars.ContainsKey(self.aapl):
            aapl_close = data.Bars[self.aapl].Close

            if self.previous_aapl_close is not None and aapl_close < self.previous_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

            self.previous_aapl_close = aapl_close

        current_spy_sma_delta = None
        if data.Bars.ContainsKey(self.spy) and self.spy_sma.IsReady:
            current_spy_sma_delta = data.Bars[self.spy].Close - self.spy_sma.Current.Value

        if not all(data.Bars.ContainsKey(symbol) for symbol in self.symbols):
            if current_spy_sma_delta is not None:
                self.previous_spy_sma_delta = current_spy_sma_delta
            return

        indicators_ready = (
            self.spy_sma.IsReady
            and self.aapl_rsi.IsReady
            and self.previous_spy_sma_delta is not None
        )

        sma_cross = False
        if indicators_ready:
            sma_cross = (
                (self.previous_spy_sma_delta < 0 and current_spy_sma_delta >= 0)
                or (self.previous_spy_sma_delta > 0 and current_spy_sma_delta <= 0)
            )

        if indicators_ready:
            if self.a_lot > 0 and not self.a_pending and sma_cross:
                self._submit_order(self.spy, -self.a_lot, "A", "sell")

            if self.b_lot > 0 and not self.b_pending and self.aapl_rsi.Current.Value > 60:
                self._submit_order(self.aapl, -self.b_lot, "B", "sell")

            if self.a_lot == 0 and not self.a_pending and sma_cross:
                close = data.Bars[self.spy].Close
                quantity = int(float(self.Portfolio.TotalPortfolioValue) * 0.40 / float(close))
                if quantity > 0:
                    self._submit_order(self.spy, quantity, "A", "buy")

            if self.b_lot == 0 and not self.b_pending and self.aapl_red_streak >= 3:
                close = data.Bars[self.aapl].Close
                if self.Portfolio.Cash >= 20000:
                    quantity = int(20000 / float(close))
                    if quantity > 0:
                        self._submit_order(self.aapl, quantity, "B", "buy")

        if current_spy_sma_delta is not None:
            self.previous_spy_sma_delta = current_spy_sma_delta

    def _submit_order(self, symbol, quantity, strategy, action):
        ticket = self.MarketOrder(symbol, quantity)
        self.order_actions[ticket.OrderId] = (strategy, action)

        if strategy == "A":
            self.a_pending = True
        else:
            self.b_pending = True

    def OnOrderEvent(self, orderEvent):
        if orderEvent.OrderId not in self.order_actions:
            return

        strategy, action = self.order_actions[orderEvent.OrderId]

        if orderEvent.Status in [OrderStatus.PartiallyFilled, OrderStatus.Filled]:
            if strategy == "A":
                self.a_lot += orderEvent.FillQuantity
            else:
                self.b_lot += orderEvent.FillQuantity

        if orderEvent.Status in [OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid]:
            if strategy == "A":
                self.a_pending = False
            else:
                self.b_pending = False
