class IndependentDailyStrategies(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)
        self.SetWarmUp(101, Resolution.Daily)

        self.symbols = {
            ticker: self.AddEquity(ticker, Resolution.Daily).Symbol
            for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        }

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        self.spy_sma = SimpleMovingAverage(100)
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)
        self.spy_sma_distances = RollingWindow[float](2)

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0

        self.previous_aapl_close = None
        self.aapl_red_streak = 0

    def OnData(self, data: Slice):
        for symbol in self.symbols.values():
            if data.Bars.ContainsKey(symbol):
                bar = data.Bars[symbol]

                if symbol == self.spy:
                    self.spy_sma.Update(bar.EndTime, bar.Close)
                    if self.spy_sma.IsReady:
                        self.spy_sma_distances.Add(
                            float(bar.Close - self.spy_sma.Current.Value)
                        )

                elif symbol == self.aapl:
                    self.aapl_rsi.Update(bar.EndTime, bar.Close)

                    if self.previous_aapl_close is not None:
                        if bar.Close < self.previous_aapl_close:
                            self.aapl_red_streak += 1
                        else:
                            self.aapl_red_streak = 0

                    self.previous_aapl_close = bar.Close

        if self.IsWarmingUp:
            return

        if not all(data.Bars.ContainsKey(symbol) for symbol in self.symbols.values()):
            return

        if not (
            self.spy_sma.IsReady
            and self.aapl_rsi.IsReady
            and self.spy_sma_distances.IsReady
        ):
